#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    if (N == 2) {
        cout << -1 << '\n';
        return 0;
    }

    if (N % 2 == 1) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j) cout << ' ';
                cout << i * N + j + 1;
            }
            cout << '\n';
        }
    } else {
        long long M = 1LL * N * (N - 1) / 2;

        for (int i = 0; i < N; i++) {
            long long offset;
            if (i <= N - 2) {
                offset = M * i;
            } else {
                offset = M * (1LL * (N - 2) * (N + 1) / 2);
            }

            for (int j = 0; j < N; j++) {
                long long base;
                if (j <= N - 2) {
                    base = j + 1;
                } else {
                    base = M;
                }

                if (j) cout << ' ';
                cout << offset + base;
            }
            cout << '\n';
        }
    }

    return 0;
}
